head.script:
// 전역 변수
scwin.popupMode = "new"; // "new", "edit", "view"
scwin.parentCallback = null;

scwin.onpageload = function () {
    // 기본 설정
    scwin.setEditorMode(true); // 기본적으로 편집 모드
    scwin.hideAllPreviewPanels();
    scwin.showNoPreview();
};

// 외부에서 호출할 수 있는 공용 함수들
scwin.setIssueData = function(data) {
    if (data) {
        dmp_issVoDetail.setJSON(data);
        if (data.id) {
            scwin.loadFileList();
        }
    }
};

scwin.getIssueData = function() {
    return dmp_issVoDetail.getJSON();
};

scwin.setPopupMode = function(mode, callback) {
    scwin.popupMode = mode;
    scwin.parentCallback = callback;

    if (mode === "new") {
        spn_popupTitle.setValue("이슈리스크 등록");
        btn_save.show();
        btn_edit.hide();
        btn_delete.hide();
        scwin.setEditorMode(true);
    } else if (mode === "edit") {
        spn_popupTitle.setValue("이슈리스크 수정");
        btn_save.hide();
        btn_edit.show();
        btn_delete.show();
        scwin.setEditorMode(false);
    } else if (mode === "view") {
        spn_popupTitle.setValue("이슈리스크 상세보기");
        btn_save.hide();
        btn_edit.show();
        btn_delete.show();
        scwin.setEditorMode(false);
    }
};

/************************** 버튼 이벤트 *************************/

// 저장 버튼
scwin.btn_save_onclick = function (e) {
    var issueName = dmp_issVoDetail.get("name");
    if (!issueName || issueName.trim() === "") {
        $c.win.alert("이슈/리스크명을 입력해주세요.");
        return;
    }

    scwin.sendIssueAndFiles();
};

// 수정 버튼
scwin.btn_edit_onclick = function (e) {
    var issueId = dmp_issVoDetail.get("id");
    var issueName = dmp_issVoDetail.get("name");

    if (!issueId || issueId.trim() === "") {
        $c.win.alert("이슈 ID가 없습니다.");
        return;
    }

    if (!issueName || issueName.trim() === "") {
        $c.win.alert("이슈/리스크명을 입력해주세요.");
        return;
    }

    var promise = $c.win.confirm("수정하시겠습니까?");
    promise.then(function (result) {
        if (result) {
            $c.sbm.execute($p, sbm_updateIssVo);
        }
    });
};

// 삭제 버튼
scwin.btn_delete_onclick = function (e) {
    var issueId = dmp_issVoDetail.get("id");

    if (!issueId) {
        $c.win.alert("삭제할 이슈를 선택해주세요.");
        return;
    }

    var promise = $c.win.confirm("삭제하시겠습니까?\n관련된 파일도 함께 삭제됩니다.");
    promise.then(function (result) {
        if (result) {
            $c.sbm.execute($p, sbm_deleteIssVo);
        }
    });
};

// 초기화 버튼
scwin.btn_reset_onclick = function (e) {
    dmp_issVoDetail.setEmptyValue();
    dlt_upload.setJSON([]);
    dlt_attVoList.setJSON([]);
    if (mpd_html5Type && mpd_html5Type.removeAllFiles) {
        mpd_html5Type.removeAllFiles();
    }
    scwin.hideAllPreviewPanels();
    scwin.showNoPreview();
};

// 닫기 버튼
scwin.btn_close_onclick = function (e) {
    $p.closeWindow();
};

/************************** 이슈 CRUD 관련 함수 *************************/

// 이슈와 파일 전송
scwin.sendIssueAndFiles = function () {
    console.log("sendIssueAndFiles() 시작됨");

    var formData = new FormData();
    formData.append("pjtId", dmp_issVoDetail.get("pjtId"));
    formData.append("name", dmp_issVoDetail.get("name"));
    formData.append("userId", dmp_issVoDetail.get("userId"));
    formData.append("dueDate", dmp_issVoDetail.get("dueDate"));
    formData.append("status", dmp_issVoDetail.get("status") || "PEN");
    formData.append("priority", dmp_issVoDetail.get("priority") || "MD");
    formData.append("description", dmp_issVoDetail.get("description"));
    formData.append("responsePlan", dmp_issVoDetail.get("responsePlan"));
    formData.append("resolvedDate", dmp_issVoDetail.get("resolvedDate"));

    // 파일 추가
    if (mpd_html5Type && mpd_html5Type.fileArray) {
        var fileList = mpd_html5Type.fileArray;
        if (fileList && fileList.length > 0) {
            for (var i = 0; i < fileList.length; i++) {
                var realFile = fileList[i].file;
                formData.append("files", realFile);
            }
        }
    }

    fetch("/InsWebApp/ISS001InsWithFiles.pwkjson", {
        method: "POST",
        body: formData
    })
    .then(function(res) { return res.json(); })
    .then(function(res) {
        $c.win.alert("등록되었습니다.");
        if (scwin.parentCallback) {
            scwin.parentCallback();
        }
        $p.closeWindow();
    })
    .catch(function(err) {
        console.error("전송 실패", err);
        $c.win.alert("트랜잭션 실패");
    });
};

// 수정 완료 콜백
scwin.sbm_updateIssVo_submitdone = function (e) {
    var elHeader = e.responseJSON.elHeader;
    if (!elHeader || elHeader.resSuc == false) {
        $c.win.alert(`에러코드 : ${elHeader.resCode}\n에러메시지 : ${elHeader.resMsg}`);
        return false;
    }

    $c.win.alert("수정되었습니다.");
    if (scwin.parentCallback) {
        scwin.parentCallback();
    }
    $p.closeWindow();
};

// 삭제 완료 콜백
scwin.sbm_deleteIssVo_submitdone = function (e) {
    var elHeader = e.responseJSON.elHeader;
    if (!elHeader || elHeader.resSuc == false) {
        $c.win.alert(`에러코드 : ${elHeader.resCode}\n에러메시지 : ${elHeader.resMsg}`);
        return false;
    }

    $c.win.alert("삭제되었습니다.");
    if (scwin.parentCallback) {
        scwin.parentCallback();
    }
    $p.closeWindow();
};

/************************** 파일 관련 함수 *************************/

// 파일 목록 로드
scwin.loadFileList = function() {
    console.log("=== 파일 목록 로드 시작 ===");

    var issueId = dmp_issVoDetail.get("id");
    console.log("이슈 ID:", issueId);

    if (!issueId || issueId.trim() === "") {
        console.log("이슈 ID가 없습니다. 파일 목록을 초기화합니다.");
        dlt_attVoList.setJSON([]);
        scwin.hideAllPreviewPanels();
        scwin.showNoPreview();
        return;
    }

    dmp_fileSearch.set("id", issueId);
    $c.sbm.execute($p, sbm_getIssFileList);
};

// 파일 목록 조회 성공 콜백
scwin.sbm_getIssFileList_submitdone = function(e) {
    console.log("=== 파일 목록 조회 응답 처리 ===");
    console.log("responseJSON:", e.responseJSON);

    var elData = e.responseJSON.elData;
    var elHeader = e.responseJSON.elHeader;

    if (!elHeader || elHeader.resSuc == false) {
        console.error("파일 목록 조회 실패:", elHeader ? elHeader.resMsg : "알 수 없는 오류");
        return false;
    }

    var fileList = elData.attVoList || [];
    console.log("파일 목록 설정 완료:", fileList.length, "개");
    console.log("dlt_attVoList 총 행 수:", dlt_attVoList.getTotalRow());
};

// 파일 그리드 셀 클릭 이벤트 (미리보기)
scwin.grd_fileList_oncellclick = function(row, col, colId) {
    var rowData = dlt_attVoList.getRowJSON(row);

    if (colId === "originalFileName") {
        scwin.previewFile(rowData.fileId, rowData.originalFileName, rowData.fileExtension);
    }
};

// 파일 그리드 액션 버튼 클릭 이벤트
scwin.fileActionClick = function(row, col, colId, targetId) {
    var rowData = dlt_attVoList.getRowJSON(row);
    var fileId = rowData.fileId;
    var fileName = rowData.originalFileName;

    if (targetId.indexOf("download") >= 0 || col === 3) {
        scwin.downloadFile(fileId, fileName);
    } else if (targetId.indexOf("delete") >= 0) {
        scwin.deleteFile(fileId);
    }
};

// 파일 미리보기 함수
scwin.previewFile = function(fileId, fileName, fileExtension) {
    console.log("파일 미리보기:", fileName, fileExtension);

    dmp_currentFile.set("fileId", fileId);
    dmp_currentFile.set("originalFileName", fileName);
    dmp_currentFile.set("fileExtension", fileExtension);

    scwin.hideAllPreviewPanels();

    var ext = fileExtension ? fileExtension.toLowerCase() : "";

    if (scwin.isImageFile(ext)) {
        scwin.showImagePreview(fileId, fileName);
    } else if (scwin.isTextFile(ext)) {
        scwin.showTextPreview(fileId, fileName);
    } else if (scwin.isDocumentFile(ext)) {
        scwin.showDocumentPreview(fileId, fileName, ext);
    } else {
        scwin.showUnsupportedPreview(fileName);
    }
};

// 파일 타입 체크 함수들
scwin.isImageFile = function(ext) {
    var imageExts = ['jpg', 'jpeg', 'png', 'gif', 'bmp', 'svg', 'webp'];
    return imageExts.indexOf(ext) !== -1;
};

scwin.isTextFile = function(ext) {
    var textExts = ['txt', 'log', 'csv', 'json', 'xml', 'html', 'css', 'js', 'java', 'sql', 'properties'];
    return textExts.indexOf(ext) !== -1;
};

scwin.isDocumentFile = function(ext) {
    var docExts = ['pdf', 'doc', 'docx', 'xls', 'xlsx', 'ppt', 'pptx', 'hwp'];
    return docExts.indexOf(ext) !== -1;
};

// 모든 미리보기 패널 숨기기
scwin.hideAllPreviewPanels = function() {
    try {
        grp_noPreview.hide();
        grp_imagePreview.hide();
        grp_textPreview.hide();
        grp_documentPreview.hide();
    } catch(e) {
        console.log("미리보기 패널 숨기기 오류:", e);
    }
};

// 기본 미리보기 표시
scwin.showNoPreview = function() {
    try {
        grp_noPreview.show();
    } catch(e) {
        console.log("기본 미리보기 표시 오류:", e);
    }
};

// 이미지 미리보기 표시
scwin.showImagePreview = function(fileId, fileName) {
    var imageUrl = "/InsWebApp/ImagePreview.pwkjson?fileId=" + fileId;

    try {
        txt_previewFileName.setValue(fileName);
        grp_imagePreview.show();

        setTimeout(function() {
            var imgElement = document.getElementById("img_preview");
            if (imgElement) {
                imgElement.src = imageUrl;
                imgElement.style.width = "150px";
                imgElement.style.height = "150px";
                imgElement.style.objectFit = "cover";
                imgElement.style.border = "1px solid #ddd";
                imgElement.style.background = "white";
                imgElement.style.boxShadow = "0 2px 8px rgba(0,0,0,0.1)";
                imgElement.style.borderRadius = "4px";

                imgElement.onerror = function() {
                    scwin.showUnsupportedPreview(fileName, "이미지를 로드할 수 없습니다.");
                };
            }
        }, 100);
    } catch(e) {
        console.error("이미지 미리보기 오류:", e);
        scwin.showUnsupportedPreview(fileName);
    }
};

// 텍스트 파일 미리보기 표시
scwin.showTextPreview = function(fileId, fileName) {
    try {
        txt_textFileName.setValue(fileName);
        grp_textPreview.show();

        fetch("/InsWebApp/FilePreview.pwkjson?fileId=" + fileId)
            .then(function(response) { return response.text(); })
            .then(function(text) {
                if (text.length > 5000) {
                    text = text.substring(0, 5000) + "\n\n... (파일 내용이 길어서 일부만 표시됩니다)";
                }
                txt_textContent.setValue(text);
            })
            .catch(function(error) {
                console.error("텍스트 파일 로드 실패:", error);
                txt_textContent.setValue("텍스트 파일을 로드할 수 없습니다.");
            });
    } catch(e) {
        console.error("텍스트 미리보기 오류:", e);
        scwin.showUnsupportedPreview(fileName);
    }
};

// 문서 파일 미리보기 표시
scwin.showDocumentPreview = function(fileId, fileName, ext) {
    try {
        txt_documentFileName.setValue(fileName);

        var fileInfo = "";
        switch(ext) {
            case 'pdf':
                fileInfo = "PDF 문서 파일입니다.";
                break;
            case 'doc':
            case 'docx':
                fileInfo = "Microsoft Word 문서입니다.";
                break;
            case 'xls':
            case 'xlsx':
                fileInfo = "Microsoft Excel 스프레드시트입니다.";
                break;
            case 'ppt':
            case 'pptx':
                fileInfo = "Microsoft PowerPoint 프레젠테이션입니다.";
                break;
            case 'hwp':
                fileInfo = "한글 문서 파일입니다.";
                break;
            default:
                fileInfo = "문서 파일입니다.";
        }

        txt_documentInfo.setValue(fileInfo);
        grp_documentPreview.show();
    } catch(e) {
        console.error("문서 미리보기 오류:", e);
        scwin.showUnsupportedPreview(fileName);
    }
};

// 지원하지 않는 파일 미리보기
scwin.showUnsupportedPreview = function(fileName, message) {
    scwin.hideAllPreviewPanels();
    scwin.showNoPreview();
};

// 파일 다운로드
scwin.downloadFile = function(fileId, fileName) {
    if (!fileId || !fileName) {
        alert("다운로드할 파일 정보가 없습니다.");
        return;
    }

    try {
        var downloadUrl = "/InsWebApp/FileDownload.pwkjson?fileId=" + encodeURIComponent(fileId);

        var iframe = document.createElement('iframe');
        iframe.style.display = 'none';
        iframe.src = downloadUrl;
        document.body.appendChild(iframe);

        setTimeout(function() {
            if (iframe.parentNode) {
                document.body.removeChild(iframe);
            }
        }, 2000);

    } catch (error) {
        console.error("파일 다운로드 실패:", error);
        alert("파일 다운로드 중 오류가 발생했습니다.");
    }
};

// 파일 삭제
scwin.deleteFile = function(fileId) {
    if (!fileId) {
        alert("삭제할 파일을 선택해주세요.");
        return;
    }

    var promise = $c.win.confirm("파일을 삭제하시겠습니까?");
    promise.then(function(result) {
        if (result) {
            $c.sbm.execute($p, {
                id: "sbm_deleteFile",
                action: "/InsWebApp/ISS001FileDelete.pwkjson",
                submitData: {
                    fileId: fileId
                },
                isProcessMsg: false,
                submitDone: function(e) {
                    var elHeader = e.responseJSON.elHeader;
                    if (elHeader && elHeader.resSuc === true) {
                        alert("파일이 삭제되었습니다.");

                        if (dmp_currentFile.get("fileId") === fileId) {
                            scwin.hideAllPreviewPanels();
                            scwin.showNoPreview();
                            dmp_currentFile.setEmptyValue();
                        }

                        scwin.loadFileList();
                    } else {
                        alert("파일 삭제 실패: " + (elHeader ? elHeader.resMsg : "알 수 없는 오류"));
                    }
                },
                submitError: function(e) {
                    console.error("파일 삭제 실패:", e);
                    alert("파일 삭제 중 오류가 발생했습니다.");
                }
            });
        }
    });
};

// 현재 미리보기 중인 파일 다운로드
scwin.downloadCurrentFile = function() {
    var fileId = dmp_currentFile.get("fileId");
    var fileName = dmp_currentFile.get("originalFileName");

    if (fileId && fileName) {
        scwin.downloadFile(fileId, fileName);
    } else {
        alert("다운로드할 파일 정보가 없습니다.");
    }
};

/************************** 파일 업로드 관련 함수 *************************/

// 파일 선택 완료 콜백
scwin.multiUploadSelectDone = function () {
    console.log("파일 선택 완료 콜백 실행");
    var fileInfos = mpd_html5Type.getFileInfos();
    var newFileData = [];

    for (var i = 0; i < fileInfos.length; i++) {
        var file = fileInfos[i];
        newFileData.push({
            originalFileName: file.name,
            fileSize: file.size,
            fileExtension: scwin.getFileExtension(file.name),
            status: "업로드 대기",
            action: "❌"
        });
    }

    dlt_upload.setJSON(newFileData);
    try {
        grd_uploadList.refresh();
    } catch(e) {
        console.log("그리드 새로고침 실패, 무시");
    }

    console.log("업로드 대기 파일 수:", newFileData.length);
};

// 파일 확장자 추출
scwin.getFileExtension = function(fileName) {
    if (!fileName || fileName.indexOf('.') === -1) return '';
    return fileName.split('.').pop().toLowerCase();
};

// 업로드 파일 삭제
scwin.removeUploadFile = function(row, col, colId, targetId) {
    console.log("업로드 파일 삭제:", row);

    try {
        dlt_upload.removeRow(row);

        if (mpd_html5Type && mpd_html5Type.removeFileByIndex) {
            mpd_html5Type.removeFileByIndex(row);
        } else if (mpd_html5Type && mpd_html5Type.fileArray) {
            mpd_html5Type.fileArray.splice(row, 1);
        }

        try {
            grd_uploadList.refresh();
        } catch(e) {
            console.log("그리드 새로고침 실패, 무시");
        }

    } catch(error) {
        console.error("파일 삭제 중 오류:", error);
        alert("파일 삭제 중 오류가 발생했습니다.");
    }
};

// 파일 업로드 초기화
scwin.btn_InitMultiupload_onclick = function(e) {
    dlt_upload.removeAll();
    if (mpd_html5Type) {
        if (mpd_html5Type.clear) {
            mpd_html5Type.clear();
        } else if (mpd_html5Type.removeAllFiles) {
            mpd_html5Type.removeAllFiles();
        } else if (mpd_html5Type.fileArray) {
            mpd_html5Type.fileArray = [];
        }
    }
};

/************************** 에디터 관련 함수 *************************/

// 에디터 모드 전환 함수
scwin.setEditorMode = function(isEditMode) {
    console.log("에디터 모드 전환:", isEditMode ? "편집" : "조회");

    if (isEditMode) {
        grp_description_edit.show();
        grp_description_view.hide();
        grp_response_edit.show();
        grp_response_view.hide();
    } else {
        grp_description_edit.hide();
        grp_description_view.show();
        grp_response_edit.hide();
        grp_response_view.show();

        scwin.updateViewContent();
    }
};

// 조회 모드에서 HTML 내용을 텍스트로 변환
scwin.updateViewContent = function() {
    try {
        var description = dmp_issVoDetail.get("description") || "";
        var responsePlan = dmp_issVoDetail.get("responsePlan") || "";

        var descriptionText = scwin.stripHtmlTags(description);
        var responsePlanText = scwin.stripHtmlTags(responsePlan);

        txt_description_view.setValue(descriptionText);
        txt_response_view.setValue(responsePlanText);

    } catch(e) {
        console.error("내용 업데이트 실패:", e);
    }
};

// HTML 태그 제거 함수
scwin.stripHtmlTags = function(htmlString) {
    if (!htmlString) return "";

    var text = htmlString.replace(/<[^>]*>/g, "");

    text = text.replace(/&nbsp;/g, " ");
    text = text.replace(/&lt;/g, "<");
    text = text.replace(/&gt;/g, ">");
    text = text.replace(/&amp;/g, "&");
    text = text.replace(/&quot;/g, '"');

    text = text.replace(/\s+/g, " ").trim();

    return text;
};
